        int i = output_idx / d2;
        int k = output_idx - i * d2;
        for (int r = threadIdx.x; r < d0; r += blockDim.x) {
            local_max = cute_max_combine(local_max, input(r, i, k));
        }
    } else {
        int b = output_idx / d1;
        int i = output_idx - b * d1;
        for (int r = threadIdx.x; r < d2; r += blockDim.x) {
            local_max = cute_max_combine(local_max, input(b, i, r));
        }
    }
    int lane = threadIdx.x & 31;
    int warp_id = threadIdx.x >> 5;
    for (int offset = 16; offset > 0; offset >>= 1) {
        scalar_t other = cute_shfl_down(local_max, offset);
        local_max = cute_max_combine(local_max, other);
    }
    extern __shared__ unsigned char shared_raw[];
    scalar_t* shared = reinterpret_cast<scalar_t*>(shared_raw);
    if (lane == 0) {
        shared[warp_id] = local_max;
    }
    __syncthreads();
    constexpr int num_warps = 8;
    if (warp_id == 0) {
        local_max = lane < num_warps
            ? shared[lane]
            : -std::numeric_limits<scalar_t>::infinity();
        for (int offset = 16; offset > 0; offset >>= 1) {
            scalar_t other = cute_shfl_down(local_max, offset);
            local_max = cute_max_combine(local_max, other);
        }
        if (lane == 0) {
            y[output_idx] = local_max;
        }
