torch::Tensor cute_max_reduce(torch::Tensor x, int64_t dim)
{
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.dim() == 3, "x must be a 3D tensor");
    TORCH_CHECK(dim >= 0 && dim < 3, "dim must be 0, 1, or 2");
    TORCH_CHECK(
        x.scalar_type() == at::kFloat ||
        x.scalar_type() == at::kDouble ||
        x.scalar_type() == at::kHalf,
        "supported dtypes are float16, float32, and float64");

    auto x_contiguous = x.contiguous();

    int d0 = static_cast<int>(x_contiguous.size(0));
    int d1 = static_cast<int>(x_contiguous.size(1));
    int d2 = static_cast<int>(x_contiguous.size(2));

    std::vector<int64_t> output_shape;
    if (dim == 0) {
        output_shape = {d1, d2};
    } else if (dim == 1) {
        output_shape = {d0, d2};
    } else {
        output_shape = {d0, d1};
    }

    auto output = torch::empty(output_shape, x.options());
    int output_size = static_cast<int>(output.numel());

    constexpr int threads = 256;
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

     AT_DISPATCH_FLOATING_TYPES_AND_HALF(
         x.scalar_type(),
         "cute_max_reduce",
         [&] {
             if (dim == 1) {
                 constexpr int tiled_threads = 256;
                 int tiles_per_batch = (d2 + tiled_threads - 1) / tiled_threads;
                 cute_max_reduce_dim1_tiled_kernel<scalar_t>
                     <<<d0 * tiles_per_batch, tiled_threads, 0, stream>>>(
                         x_contiguous.data_ptr<scalar_t>(),
                         output.data_ptr<scalar_t>(),
                         d0,
                         d1,
                         d2,
                         tiles_per_batch);
             } else {
                 cute_max_reduce_kernel<scalar_t>
                     <<<output_size, threads, (threads / 32) * sizeof(scalar_t), stream>>>(
                         x_contiguous.data_ptr<scalar_t>(),
                         output.data_ptr<scalar_t>(),
                         d0,
                         d1,
                         d2,
                         static_cast<int>(dim),
                         output_size);
             }
         });

    TORCH_CHECK(
        cudaGetLastError() == cudaSuccess,
        "CUTE max-reduction kernel launch failed");

    return output;
